                <span style={{ display: 'inline-flex', alignItems: 'center', gap: '4px', padding: '2px 9px', borderRadius: '20px', fontSize: '11.5px', fontWeight: 700, background: st.bg, color: st.color, border: `1px solid ${st.border}` }}>
